-- Unnormalized table
CREATE TABLE Orders (
    OrderId INT,
    CustomerName VARCHAR(100),
    Product1 VARCHAR(50),
    Product2 VARCHAR(50)
);

-- 1NF: Separate products into rows
CREATE TABLE Orders (
    OrderId INT,
    CustomerName VARCHAR(100),
    Product VARCHAR(50)
);

-- 2NF/3NF: Separate customers
CREATE TABLE Customers (
    CustomerId INT PRIMARY KEY,
    CustomerName VARCHAR(100)
);

CREATE TABLE Orders (
    OrderId INT PRIMARY KEY,
    CustomerId INT FOREIGN KEY REFERENCES Customers(CustomerId),
    Product VARCHAR(50)
);
